public class AltCryonicProjectileEntity
extends AbstractArrow
implements ItemSupplier {
    public static final ItemStack PROJECTILE_ITEM = new ItemStack((ItemLike)ThermalShockModBlocks.BLUE_ORB.get());

    public AltCryonicProjectileEntity(PlayMessages.SpawnEntity packet, Level world) {
        super((EntityType)ThermalShockModEntities.ALT_CRYONIC_PROJECTILE.get(), world);
    }

    public AltCryonicProjectileEntity(EntityType<? extends AltCryonicProjectileEntity> type, Level world) {
        super(type, world);
