    public HighDirectorSopelEntity(PlayMessages.SpawnEntity packet, Level world) {
        this((EntityType<HighDirectorSopelEntity>)((EntityType)ThermalShockModEntities.HIGH_DIRECTOR_SOPEL.get()), world);
    }

    public HighDirectorSopelEntity(EntityType<HighDirectorSopelEntity> type, Level world) {
        super(type, world);
        this.xpReward = 10000;
        this.setNoAi(false);
        this.setMaxUpStep(1.0f);
        this.setPersistenceRequired();
    }

    protected void defineSynchedData() {
        super.defineSynchedData();
        this.entityData.define(SHOOT, (Object)false);
        this.entityData.define(ANIMATION, (Object)"undefined");
